WITH memberships AS (SELECT reader_key,group_id FROM f_seed_members WHERE reader_key IN (unhex('68756d616e2d30'))), indexed AS (SELECT author_key,doc_id,group_id FROM doc_groups_t WHERE group_id IN (SELECT group_id FROM memberships)), docs AS (SELECT author_key,doc_id,created_at,deleted,row_number() OVER (PARTITION BY author_key,doc_id ORDER BY updated_at DESC,deleted DESC) AS rn FROM documents WHERE (author_key,doc_id) IN (SELECT author_key,doc_id FROM indexed)), links AS (SELECT doc_id,group_id,deleted,row_number() OVER (PARTITION BY doc_id,group_id ORDER BY updated_at DESC,deleted DESC) AS rn FROM doc_groups WHERE (doc_id,group_id) IN (SELECT doc_id,group_id FROM indexed)), routes AS (SELECT m.reader_key AS reader_key,d.created_at AS created_at,d.author_key AS author_key,d.doc_id AS doc_id,g.group_id AS group_id FROM docs AS d INNER JOIN links AS g ON d.doc_id=g.doc_id INNER JOIN memberships AS m ON g.group_id=m.group_id WHERE d.rn=1 AND d.deleted=0 AND g.rn=1 AND g.deleted=0), ranked AS (SELECT *,dense_rank() OVER (PARTITION BY reader_key ORDER BY created_at DESC,doc_id DESC,author_key DESC) AS position FROM routes) SELECT reader_key,toUnixTimestamp64Milli(created_at) AS created_ms,author_key,doc_id,group_id,2 AS version,0 AS deleted FROM ranked WHERE position<=200 ORDER BY reader_key,created_ms DESC,doc_id DESC,author_key DESC,group_id FORMAT JSON